/**
 * SieReach Meta - Fake Account & Ad Bot Traffic Detection Engine
 * Analyzes conversational behavior, Meta Graph API delivery errors, profile completeness,
 * and unresponsiveness patterns to classify leads as Verified Humans, Suspicious, or Confirmed Fakes.
 */

export interface AuthenticityScoreResult {
  score: number; // 0 to 100
  status: "VERIFIED_HUMAN" | "SUSPICIOUS" | "CONFIRMED_FAKE";
  reasons: string[];
}

// Known automated default icebreaker buttons generated by Meta Ads
const DEFAULT_META_ICEBREAKERS = [
  "is anyone available to chat?",
  "can i learn more about your business?",
  "can someone help me?",
  "hi! please let me know how i can help.",
  "can you tell me more about your ad?",
  "what are your hours?",
  "where are you located?",
  "hi",
  "hello",
  "...",
  ".",
  "👍",
];

export function detectLeadAuthenticity(lead: {
  customerName: string;
  customerAvatar?: string | null;
  lastCustomerMessage: string;
  status: string;
  followUpCount: number;
  repliedAt?: Date | null;
  repliedAfterStep?: number | null;
  lastError?: string | null;
}): AuthenticityScoreResult {
  let score = 0;
  const reasons: string[] = [];

  const rawMsg = (lead.lastCustomerMessage || "").trim().toLowerCase();
  const isReplied = lead.status === "REPLIED" || lead.repliedAt !== null;

  // 1. Meta Graph API Delivery Failure Check (Error 551 / 200 = Confirmed Fake/Deactivated)
  if (lead.lastError) {
    const err = lead.lastError.toLowerCase();
    if (
      err.includes("551") ||
      err.includes("not available on messenger") ||
      err.includes("deactivated") ||
      err.includes("200") ||
      err.includes("permissions error")
    ) {
      return {
        score: 100,
        status: "CONFIRMED_FAKE",
        reasons: ["Account deactivated or banned by Meta (Graph API Error #551/#200)"],
      };
    }
  }

  // If customer replied after follow-up, they are definitely human
  if (isReplied) {
    return {
      score: 0,
      status: "VERIFIED_HUMAN",
      reasons: ["Active buyer (verified real human response)"],
    };
  }

  // 2. Default Meta Icebreaker Button Analysis
  const isDefaultButton = DEFAULT_META_ICEBREAKERS.some(
    (icebreaker) => rawMsg === icebreaker || rawMsg.startsWith(icebreaker)
  );

  if (isDefaultButton) {
    score += 40;
    reasons.push("Default automated icebreaker clicker only (never typed custom inquiry)");
  } else if (rawMsg.length > 25 && (rawMsg.includes("?") || rawMsg.includes("size") || rawMsg.includes("shipping") || rawMsg.includes("price") || rawMsg.includes("cod"))) {
    // Highly specific human inquiry
    score = Math.max(0, score - 30);
  }

  // 3. Profile Authenticity Signals
  const isMissingAvatar = !lead.customerAvatar || lead.customerAvatar.includes("placeholder") || lead.customerAvatar.includes("default");
  if (isMissingAvatar) {
    score += 25;
    reasons.push("Missing or blank default profile photo");
  }

  const name = (lead.customerName || "").trim();
  const isBotName =
    name.toLowerCase().startsWith("user_") ||
    name.toLowerCase().startsWith("facebook user") ||
    name.length <= 2 ||
    /^\d+$/.test(name);

  if (isBotName) {
    score += 25;
    reasons.push("Suspicious or auto-generated account username pattern");
  }

  // 4. Outreach Responsiveness (Ghosted multiple follow-ups with 0 engagement)
  if (lead.followUpCount >= 2) {
    score += 25;
    reasons.push("100% dead engagement across Step 1 & Step 2 follow-ups");
  } else if (lead.followUpCount === 1) {
    score += 10;
  }

  // Clamp score
  score = Math.min(100, Math.max(0, score));

  let status: AuthenticityScoreResult["status"] = "VERIFIED_HUMAN";
  if (score >= 70) {
    status = "CONFIRMED_FAKE";
  } else if (score >= 40) {
    status = "SUSPICIOUS";
  } else {
    status = "VERIFIED_HUMAN";
    if (reasons.length === 0) {
      reasons.push("Organic customer with genuine inquiry patterns");
    }
  }

  return {
    score,
    status,
    reasons,
  };
}
